fn is_prime(n: i8) -> bool {
    // Handle edge cases: negative numbers, 0, and 1 are not prime
    if n < 2 {
        return false;
    }
    
    // Convert to u8 for safe arithmetic operations
    let n_abs = n.unsigned_abs() as u8;
    
    // Check divisibility by numbers from 2 up to sqrt(n)
    // We only need to check up to sqrt(n) because if n has a divisor
    // greater than sqrt(n), it must also have a divisor less than sqrt(n)
    let limit = (n_abs as f64).sqrt() as u8;
    
    let mut divisor: u8 = 2;
    
    while divisor <= limit {
        if n_abs % divisor == 0 {
            return false;
        }
        divisor += 1;
    }
    
    true
}